function geometryScene(kind,value=6){const line='fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"';let shapes='',readout='Схема показывает основные элементы фигуры.';if(kind==='circle'){const r=+value;shapes=`<circle cx="150" cy="90" r="${r*6}" ${line}/><path d="M150 90h${r*6}" ${line}/><circle cx="150" cy="90" r="3" fill="currentColor"/><text x="145" y="110">O</text><text x="${155+r*3}" y="82">r</text>`;readout=`r = ${r}; длина окружности C = ${2*r}π; площадь круга S = ${r*r}π.`}else if(kind==='triangle'){const a=+value,x=75+a*14;shapes=`<path d="M75 140V35L${x} 140Z" ${line}/><path d="M75 125h15v15" ${line}/><text x="55" y="90">6</text><text x="${(75+x)/2}" y="160">${a}</text><text x="60" y="155">A</text><text x="60" y="29">B</text><text x="${x+8}" y="148">C</text>`;readout=`Катеты ${a} и 6. Гипотенуза ≈ ${Math.hypot(a,6).toFixed(2).replace('.',',')}; площадь ${a*3}.`}else if(kind==='parallel'){shapes=`<path d="M30 55H270M30 125H270M105 170L195 10" ${line}/><text x="250" y="47">a</text><text x="250" y="117">b</text><text x="180" y="80">α</text><text x="140" y="150">α</text>`;readout='a ∥ b: соответственные углы при секущей равны.'}else if(kind==='quad'){shapes=`<path d="M55 140L100 40H260L215 140ZM100 40V140" ${line}/><text x="130" y="160">a</text><text x="105" y="100">h</text>`;readout='Высота h перпендикулярна основанию a. Площадь параллелограмма S = ah.'}else if(kind==='polygon'){shapes=`<path d="M150 20L215 55V125L150 160L85 125V55ZM150 20V90L215 55M150 90L215 125M150 90V160M150 90L85 125M150 90L85 55" ${line}/>`;readout='Правильный шестиугольник разбивается на шесть равносторонних треугольников.'}else if(kind==='sphere'){shapes=`<circle cx="150" cy="90" r="65" ${line}/><ellipse cx="150" cy="90" rx="65" ry="20" ${line} stroke-dasharray="5 5"/><path d="M150 90h65" ${line}/><text x="180" y="82">R</text>`;readout='Сфера: все её точки находятся на расстоянии R от центра.'}else if(kind==='cone'||kind==='cylinder'){shapes=kind==='cone'?`<path d="M75 140L150 25L225 140M150 25V140M150 140H225" ${line}/>`:`<path d="M75 40V140M225 40V140M150 40V140" ${line}/><ellipse cx="150" cy="40" rx="75" ry="20" ${line}/>`;shapes+=`<ellipse cx="150" cy="140" rx="75" ry="20" ${line}/><text x="158" y="90">h</text><text x="185" y="135">r</text>`;readout='h — перпендикулярная высота, r — радиус основания.'}else if(kind==='pyramid'){shapes=`<path d="M50 130L150 20L255 130L170 165ZM50 130L130 100L255 130M150 20L130 100M150 20L170 165M150 20V130" ${line}/><text x="155" y="85">h</text>`;readout='Высота h соединяет вершину с плоскостью основания по перпендикуляру.'}else{shapes=`<path d="M65 65H210V155H65ZM65 65L110 25H255V115L210 155M210 65L255 25M65 155L110 115H255M110 25V115M65 155L255 25" ${line}/><text x="125" y="174">a</text><text x="240" y="145">b</text><text x="45" y="115">h</text>`;readout='Прямоугольный параллелепипед: d² = a² + b² + h².'}return {svg:`<svg viewBox="0 0 300 185" role="img" aria-label="${readout}">${shapes}</svg>`,readout}}
function geometryHTML(kind){if(!kind)return '';if(kind==='vectors')return vectorsHTML();const s=geometryScene(kind);return `<figure class="geometry-figure" data-kind="${kind}"><div class="eyebrow">${['circle','triangle'].includes(kind)?'ИССЛЕДУЙ ФИГУРУ':'СХЕМА К ТЕМЕ'}</div><div class="geo-scene">${s.svg}</div>${['circle','triangle'].includes(kind)?`<label class="geo-slider">${kind==='circle'?'Радиус':'Катет a'}<input type="range" min="2" max="10" value="6" step="1" data-geo-control aria-label="${kind==='circle'?'Радиус окружности':'Катет прямоугольного треугольника'}"></label>`:''}<figcaption class="geo-readout">${s.readout}</figcaption><small>Учебная схема; не чертёж к конкретной задаче.</small></figure>`}
document.addEventListener('input',e=>{if(!e.target.matches('[data-geo-control]'))return;const f=e.target.closest('.geometry-figure'),s=geometryScene(f.dataset.kind,+e.target.value);f.querySelector('.geo-scene').innerHTML=s.svg;f.querySelector('.geo-readout').textContent=s.readout});
